def _normalize_key(value: str) -> str:
    return re.sub(r"[_\-]+", " ", value.strip().lower()).strip()


def _prettify_loan_type_id(loan_type_id: str) -> str:
    """Human label for an unknown/legacy id: 'hard_money' -> 'Hard Money'."""
    spaced = re.sub(r"[_\s]+", " ", loan_type_id.strip()).strip()
    return spaced.title()


def loan_type_label(loan_type_id: Optional[str]) -> str:
    if not loan_type_id:
        return ""
    for choice in LOAN_TYPE_CHOICES:
        if choice["id"] == loan_type_id:
            return choice["label"]
    # Legacy/oddly-cased values still map to their canonical label when known.
    resolved = resolve_loan_type(loan_type_id)
    if resolved:
        for choice in LOAN_TYPE_CHOICES:
            if choice["id"] == resolved:
                return choice["label"]
    return _prettify_loan_type_id(loan_type_id)


def resolve_loan_type(raw: str) -> Optional[str]:
    """Map a CSV/UI loan type string to a canonical id, or None if unrecognized."""
    value = (raw or "").strip()
    if not value:
        return None
    compact = value.lower().replace(" ", "").replace("-", "").replace("_", "")
    if compact in _LOAN_TYPE_IDS:
        return compact
    lowered = value.lower()
    if lowered in _LOAN_TYPE_IDS:
        # Always store the canonical (lowercase) id, never the raw casing.
        return lowered
    normalized = _normalize_key(value)
    if normalized in _EXTRA_ALIASES:
        return _EXTRA_ALIASES[normalized]
    for choice in LOAN_TYPE_CHOICES:
        if _normalize_key(choice["label"]) == normalized:
            return choice["id"]
        if _normalize_key(choice["id"]) == normalized:
            return choice["id"]
    return None

